export const policyPieces=['Refundable','hotel bookings','can be cancelled','until 48 hours','before check-in.','Breakfast','starts at','07:00.'];
export function cutPolicy(cut,budget=5){
 const chunks=[policyPieces.slice(0,cut),policyPieces.slice(cut)];
 const selected=chunks.find(c=>c.includes('until 48 hours'));
 return {chunks,selected,fits:selected.length<=budget,complete:selected.includes('Refundable')&&selected.includes('before check-in.')};
}
export function overlapPolicy(overlap){return {passage:policyPieces.slice(3-overlap,5),storedUnits:8+overlap,complete:overlap===3};}
export function mountChunkBench(host){
 host.innerHTML=`<details class="mini-bench"><summary>Next experiment: cut a document without losing the rule <span>2 min</span></summary><div class="bench-body"><span class="eyebrow">CHUNKING / KEEP MEANING TOGETHER</span><h2>Where would you cut?</h2><p>RAG usually retrieves passages, not whole documents. A useful chunk keeps a rule and its conditions together. Tap a cut point between phrases, or move the slider, to split this tiny hotel policy.</p><div class="paper-strip" id="chunk-paper"></div><label for="chunk-cut">Cut after phrase <output id="chunk-position"></output></label><input id="chunk-cut" type="range" min="1" max="7" value="3"><details class="chunk-capacity"><summary>Try a different context capacity</summary><label for="chunk-budget">Space for phrases <output id="chunk-budget-value">5</output></label><input id="chunk-budget" type="range" min="1" max="8" value="5"><p id="chunk-budget-state" aria-live="polite"></p></details><div class="chunk-preview" id="chunk-preview"></div><p class="bench-goal"><b>Your goal:</b> keep the full refund rule in one chunk that fits five phrase units. Leave breakfast out.</p><button id="chunk-test" class="primary">Try retrieving the rule</button><button id="chunk-reset" class="secondary bench-reset">Reset experiment</button><p id="chunk-feedback" role="status"></p><details class="overlap-lab"><summary>What if the split point cannot move?</summary><p>Keep the split after phrase 3. Copy some earlier phrases into the next chunk so the condition can travel with the deadline. Overlap preserves context, but stores repeated text.</p><label for="chunk-overlap">Repeated phrases <output id="overlap-value">0</output></label><input id="chunk-overlap" type="range" min="0" max="3" value="0"><div id="overlap-result" aria-live="polite"></div><p class="bench-goal">Restore the complete rule in the retrieved chunk. Watch the storage cost rise.</p></details><small>Phrase units make the cut visible here. Production chunking usually uses tokens and may preserve headings or overlap neighbouring passages.</small></div></details>`;
 const slider=host.querySelector('#chunk-cut'),budget=host.querySelector('#chunk-budget');
 function update(){const cut=+slider.value,{chunks,selected,fits}=cutPolicy(cut,+budget.value);host.querySelector('#chunk-budget-value').textContent=budget.value;host.querySelector('#chunk-budget-state').textContent='Retrieved chunk: '+selected.length+' phrase units. Capacity: '+budget.value+'. '+(fits?'It fits.':'It is too large.');host.querySelector('#chunk-position').textContent=cut;host.querySelector('#chunk-paper').innerHTML=policyPieces.map((p,i)=>'<span>'+p+'</span>'+(i<policyPieces.length-1?'<button class="cut-point '+(i===cut-1?'selected-cut':'')+'" data-cut="'+(i+1)+'" aria-label="Cut after phrase '+(i+1)+'" aria-pressed="'+(i===cut-1)+'">&#9986;</button>':'')).join('');host.querySelector('#chunk-preview').innerHTML=chunks.map((c,i)=>'<article class="'+(c===selected?'selected-chunk':'')+'"><span>CHUNK '+(i+1)+' / '+c.length+' units</span><p>'+c.join(' ')+'</p><small>'+(c===selected?(fits?'Retrieved: contains the 48-hour rule':'Retrieved, but too large for the window'):'Not retrieved in this example')+'</small></article>').join('');host.querySelector('#chunk-feedback').textContent='';host.querySelectorAll('[data-cut]').forEach(button=>button.onclick=()=>{slider.value=button.dataset.cut;update();host.querySelector('[data-cut="'+slider.value+'"]').focus({preventScroll:true});});}
 const overlap=host.querySelector('#chunk-overlap');const drawOverlap=()=>{const n=+overlap.value,r=overlapPolicy(n);host.querySelector('#overlap-value').textContent=n;host.querySelector('#overlap-result').innerHTML='<article class="overlap-paper"><span class="eyebrow">RETRIEVED CHUNK / '+r.passage.length+' UNITS</span><p>'+r.passage.map((phrase,i)=>i<n?'<mark>'+phrase+'</mark>':phrase).join(' ')+'</p></article><p>'+r.storedUnits+' phrase units stored across three chunks, including '+n+' repeated units.</p><strong>'+(r.complete?'Rule restored. You kept the condition and deadline together.':'The refundable condition is still missing. Add more overlap.')+'</strong>';};overlap.oninput=drawOverlap;drawOverlap();
 host.querySelector('#chunk-reset').onclick=()=>{slider.value=3;budget.value=5;overlap.value=0;update();drawOverlap();slider.focus({preventScroll:true});};
 budget.oninput=update;
 slider.oninput=update;host.querySelector('#chunk-test').onclick=()=>{const r=cutPolicy(+slider.value,+budget.value);host.querySelector('#chunk-feedback').textContent=+budget.value!==5?'Explore any capacity, then return to 5 units to solve the original challenge.':!r.fits?'The passage has the answer, but is too large. Move the cut before the breakfast information.':!r.complete?'The retrieved passage lost part of the rule. Keep the refundable condition and the check-in deadline together.':'Solved. The rule, condition and deadline travel together. Smaller is useful only when meaning survives.';};update();
}
